import java.io.*;
import java.util.*;

public class TaskD {
    private static final long[] ONE = {0, 0, 0, 0, 2, 4};
    private static final long[] TWO = {0, 0, 0, 4, 8, 10};
    private static final long[] THREE = {0, 0, 4, 8, 12, 14};

    static class In {
        BufferedReader br;
        StringTokenizer st;

        In(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        long nextLong() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (Exception e) {
                    return -1;
                }
            }
            return Long.parseLong(st.nextToken());
        }

        void close() throws IOException {
            br.close();
        }
    }

    private static long largestEven(long v) {
        return v & ~1L;
    }

    private static long lookupTable(long n, int r) {
        if (r < 0 || r > 5) return 0;
        if (n == 1) return ONE[r];
        if (n == 2) return TWO[r];
        if (n == 3) return THREE[r];
        return 0;
    }

    private static long answer(long n, long m) {
        if (n > m) {
            long t = n;
            n = m;
            m = t;
        }
        if (n > 3) return largestEven(n * m);
        long s = m - m % 6;
        int o = (int) (m % 6);
        long h = lookupTable(n, o);
        if (n + m > 9 && n > 1) return largestEven(n * m);
        return s * n + h;
    }

    public static void main(String[] args) throws IOException {
        InputStream input = System.in;
        PrintStream output = System.out;
        try {
            File f = new File("a.in");
            if (f.exists() && f.canRead()) {
                input = new FileInputStream(f);
                output = new PrintStream("a.out");
            }
        } catch (Throwable e) {
        }
        In in = new In(input);
        PrintWriter out = new PrintWriter(output);
        long n = in.nextLong();
        long m = in.nextLong();
        out.print(answer(n, m));
        in.close();
        out.close();
    }
}
